"""Visible tests for inventory.py. Do NOT edit this file."""
import sys
from decimal import Decimal as D
from inventory import parse_sku, add_stock, remove_stock, transfer, low_stock_skus, total_value

failures = []

def check(name, cond):
    if not cond:
        failures.append(name)

# parse_sku normalizes to uppercase
check("parse_sku uppercases", parse_sku("ab-1234") == "AB-1234")
check("parse_sku strips whitespace", parse_sku("  AB-1234  ") == "AB-1234")
check("parse_sku already upper", parse_sku("AB-1234") == "AB-1234")
try:
    parse_sku("ABC-1234")
    check("parse_sku rejects 3 letters", False)
except ValueError:
    check("parse_sku rejects 3 letters", True)
try:
    parse_sku("AB-123")
    check("parse_sku rejects 3 digits", False)
except ValueError:
    check("parse_sku rejects 3 digits", True)

# add_stock / remove_stock basics
inv = {}
add_stock(inv, "ab-1234", 10)
check("add_stock normalizes key", inv == {"AB-1234": 10})
add_stock(inv, "AB-1234", 5)
check("add_stock accumulates", inv["AB-1234"] == 15)
remove_stock(inv, "ab-1234", 15)
check("remove_stock removes zero-qty key", "AB-1234" not in inv)

try:
    add_stock({}, "AB-1234", 0)
    check("add_stock rejects non-positive qty", False)
except ValueError:
    check("add_stock rejects non-positive qty", True)

try:
    remove_stock({"AB-1234": 3}, "AB-1234", 5)
    check("remove_stock rejects insufficient stock", False)
except ValueError:
    check("remove_stock rejects insufficient stock", True)

# transfer must be atomic: failed transfer leaves dst untouched
src = {"AB-1234": 2}
dst = {}
try:
    transfer(src, dst, "AB-1234", 5)
    check("transfer raises on insufficient stock", False)
except ValueError:
    check("transfer raises on insufficient stock", True)
check("transfer leaves dst untouched on failure", dst == {})
check("transfer leaves src untouched on failure", src == {"AB-1234": 2})

src2 = {"AB-1234": 5}
dst2 = {}
transfer(src2, dst2, "AB-1234", 3)
check("transfer moves stock on success", src2 == {"AB-1234": 2} and dst2 == {"AB-1234": 3})

# low_stock_skus sorted by (qty, sku)
inv2 = {"CC-0001": 5, "AA-0002": 5, "BB-0003": 1}
check("low_stock_skus sorted by qty then sku", low_stock_skus(inv2, 10) == ["BB-0003", "AA-0002", "CC-0001"])

# total_value skips skus with no price
tv_inv = {"AB-1234": 3, "CD-5678": 2}
tv_prices = {"AB-1234": D("2.50")}
check("total_value skips unpriced skus", total_value(tv_inv, tv_prices) == D("7.50"))

if failures:
    print("FAILURES:", failures)
    sys.exit(1)
else:
    print("ALL OK")
